fn remove_duplicates(nums: &Vec<i32>) -> usize {
    // Handle empty array
    if nums.is_empty() {
        return 0;
    }
    
    // Start with 1 unique element (the first one)
    let mut count = 1;
    
    // Iterate through the array starting from index 1
    // Each time we see a different value from the previous one, increment count
    for i in 1..nums.len() {
        if nums[i] != nums[i - 1] {
            count += 1;
        }
    }
    
    count
}